<?php require __DIR__."/vendor/autoload.php"; $app = require_once __DIR__."/bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $files = glob(public_path("images/products/*.png")); $updated = 0; foreach ($files as $file) { $basename = basename($file, ".png"); $product = \App\Models\Product::where("name", "like", $basename)->whereNull("parent_id")->first(); if (!$product) { $product = \App\Models\Product::where("name", "like", "%" . $basename . "%")->whereNull("parent_id")->first(); } if ($product) { $imagePath = "/images/products/" . basename($file); $product->image_path = $imagePath; $product->save(); \App\Models\Product::where("parent_id", $product->id)->update(["image_path" => $imagePath]); $updated++; echo "Mapped: " . basename($file) . " -> " . $product->name . "\n"; } } echo "Total updated: $updated\n";
